#include <bits/stdc++.h>
using namespace std;

int main() {
ios::sync_with_stdio(false);
cin.tie(nullptr);
int t;
cin>>t;
cout<<endl;
while(t--){
int n; 
cin>>n;
int arr[n];
int maxi = INT_MIN;
int maxdiff = INT_MIN;
int maxdiff1 = INT_MIN;
int mini = INT_MAX;
int posmax = 0;
int posmin = 0;
vector<int> x;
for(int i = 0;i<n;i++){
cin>>arr[i];
if(i>=1){
    maxdiff = max(maxdiff, arr[i]-arr[i-1]);
}
if(arr[i]>maxi){
    maxi = arr[i];
    posmax = i;
}
if(arr[i]>mini){
    mini = arr[i];
    posmin = i;
}
}
if(posmax+ 1 == posmin||posmax-1==posmin){
int pos = max(posmax,posmin);
    for(int i = pos;i<n;i++){
        x.push_back(arr[i]);
    }
     for(int i = 0;i<pos;i++){
          x.push_back(arr[i]);
     }
    for(int i =1;i<n;i++){
        //cout<<x[i]<<endl;
        if(x[i]-x[i-1] > 0){
        maxdiff1 = max(maxdiff1, x[i]-x[i-1]);
        }
        else {
            maxdiff1 = max(maxdiff1, -x[i]+x[i-1]);
        }
    }
    cout<<maxdiff1<<endl;
   continue;
} 

cout<<maxdiff<<endl;
}
}
